import{_ as s,o as e,c as n,a6 as i}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"上手使用","description":"从熟悉新代码库到修 bug、重构、写测试、开 PR、并行开发的实操步骤","frontmatter":{"title":"上手使用","description":"从熟悉新代码库到修 bug、重构、写测试、开 PR、并行开发的实操步骤","source":"https://daiw.org/manual/claude-code/scenarios"},"headers":[],"relativePath":"manual/agent/claude-code/scenarios.md","filePath":"manual/agent/claude-code/scenarios.md"}'),p={name:"manual/agent/claude-code/scenarios.md"};function l(t,a,r,d,c,o){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="上手使用" tabindex="-1">上手使用 <a class="header-anchor" href="#上手使用" aria-label="Permalink to &quot;上手使用&quot;">​</a></h1><blockquote><p>从熟悉新代码库到修 bug、重构、写测试、开 PR、并行开发的实操步骤</p></blockquote><p>这一页是日常开发中最常用的一批操作套路（prompt recipes），照搬即可，按项目实际情况替换措辞。它们都不依赖任何特殊配置，在任何 Claude Code 界面（终端、IDE 插件、Web）都适用。</p><h2 id="快速摸清一个新代码库" tabindex="-1">快速摸清一个新代码库 <a class="header-anchor" href="#快速摸清一个新代码库" aria-label="Permalink to &quot;快速摸清一个新代码库&quot;">​</a></h2><p>刚接手一个新项目，想尽快搞清楚它的结构：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>给我讲讲这个代码库的整体情况</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这里主要用了哪些架构模式?</span></span>
<span class="line"><span>核心的数据模型是什么样的?</span></span>
<span class="line"><span>认证是怎么做的?</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>技巧</strong>：先问宽泛问题再逐步收窄；顺便让 Claude 讲讲项目里的编码约定，以及列一份项目特有术语表。如果仓库很大，给对应语言装一个代码智能插件，能让 Claude 拿到精确的“跳转到定义/查找引用”能力。</p><h2 id="定位相关代码" tabindex="-1">定位相关代码 <a class="header-anchor" href="#定位相关代码" aria-label="Permalink to &quot;定位相关代码&quot;">​</a></h2><p>需要找到和某个功能相关的代码：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>找到处理用户认证的文件</span></span>
<span class="line"><span>这些认证相关文件是怎么协作的?</span></span>
<span class="line"><span>把登录流程从前端到数据库完整梳理一遍</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>技巧</strong>：描述要尽量具体，多用项目里实际使用的术语，而不是泛泛的说法。</p><h2 id="高效修-bug" tabindex="-1">高效修 bug <a class="header-anchor" href="#高效修-bug" aria-label="Permalink to &quot;高效修 bug&quot;">​</a></h2><p>遇到报错，需要定位并修复：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>运行 npm test 时报了这个错</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>针对 user.ts 里的 @ts-ignore 建议几种修法</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>按你建议的方案，给 user.ts 加上 null 检查</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>技巧</strong>：告诉 Claude 复现问题的命令，让它自己拿到堆栈信息；说明复现步骤；告诉它这个错误是偶发还是必现。</p><h2 id="重构代码" tabindex="-1">重构代码 <a class="header-anchor" href="#重构代码" aria-label="Permalink to &quot;重构代码&quot;">​</a></h2><p>需要把老代码换成更现代的写法：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>找一下代码库里用了已废弃 API 的地方</span></span>
<span class="line"><span>针对 utils.js，给出用现代 JavaScript 特性重构的建议</span></span>
<span class="line"><span>在保持行为不变的前提下，把 utils.js 重构成 ES2024 写法</span></span>
<span class="line"><span>跑一下重构后代码对应的测试</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>技巧</strong>：让 Claude 解释新写法比旧写法好在哪；需要时明确要求保持向后兼容；重构分成小步骤、每步都可测试。</p><h2 id="补测试" tabindex="-1">补测试 <a class="header-anchor" href="#补测试" aria-label="Permalink to &quot;补测试&quot;">​</a></h2><p>给没有测试覆盖的代码补测试：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>找一下 NotificationsService.swift 里没有测试覆盖的函数</span></span>
<span class="line"><span>给通知服务补上测试</span></span>
<span class="line"><span>针对通知服务的边界条件补充测试用例</span></span>
<span class="line"><span>跑一下新测试，修复失败的部分</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Claude 会参考项目已有测试文件的风格、框架和断言方式来生成新测试。描述清楚要验证的具体行为，效果会更好；也可以直接让 Claude 帮忙找容易漏掉的边界情况、错误路径、非预期输入。</p><h2 id="创建-pull-request" tabindex="-1">创建 Pull Request <a class="header-anchor" href="#创建-pull-request" aria-label="Permalink to &quot;创建 Pull Request&quot;">​</a></h2><p>可以直接让 Claude 代劳（“帮我创建一个 PR”），也可以分步引导：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>总结一下我在认证模块做的改动</span></span>
<span class="line"><span>create a pr</span></span>
<span class="line"><span>针对安全性改进，把 PR 描述写得再详细一些</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>用 <code>gh pr create</code> 创建 PR 后，当前会话会自动与该 PR 关联，之后可以用 <code>claude --from-pr 123</code> 或在 <code>/resume</code> 选择器里粘贴 PR URL 找回这个会话。提交前记得看一眼 Claude 生成的 PR 内容，让它顺便指出潜在风险。</p><h2 id="补文档" tabindex="-1">补文档 <a class="header-anchor" href="#补文档" aria-label="Permalink to &quot;补文档&quot;">​</a></h2><p>给代码补充或更新文档：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>找一下 auth 模块里没写 JSDoc 的函数</span></span>
<span class="line"><span>给 auth.js 里没文档的函数补上 JSDoc</span></span>
<span class="line"><span>结合更多上下文和示例，完善生成的文档</span></span>
<span class="line"><span>检查一下这些文档是否符合我们的项目规范</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>技巧</strong>：明确想要的文档风格（JSDoc、docstring 等）；要求带示例；优先覆盖公共 API、接口和复杂逻辑。</p><h2 id="在非代码目录里使用" tabindex="-1">在非代码目录里使用 <a class="header-anchor" href="#在非代码目录里使用" aria-label="Permalink to &quot;在非代码目录里使用&quot;">​</a></h2><p>Claude Code 在任何目录都能工作，不只是代码仓库。在笔记库、文档目录、任意一堆 markdown 文件所在的目录里运行 <code>claude</code>，同样可以搜索、编辑、重新组织内容。<code>.claude/</code> 目录和 <code>CLAUDE.md</code> 可以和其它工具的配置目录并存不冲突。</p><h2 id="处理图片" tabindex="-1">处理图片 <a class="header-anchor" href="#处理图片" aria-label="Permalink to &quot;处理图片&quot;">​</a></h2><p>分析截图、设计稿、图表：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把截图拖进 Claude Code 窗口</span></span>
<span class="line"><span>或者复制图片后用 Ctrl+V 粘贴进 CLI(注意不是 Cmd+V)</span></span>
<span class="line"><span>或者直接告诉 Claude 图片路径:“分析这张图片:/path/to/image.png”</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这张图展示的是什么?</span></span>
<span class="line"><span>描述一下这个截图里的 UI 元素</span></span>
<span class="line"><span>根据这个设计稿生成对应的 CSS</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="用-引用文件与目录" tabindex="-1">用 @ 引用文件与目录 <a class="header-anchor" href="#用-引用文件与目录" aria-label="Permalink to &quot;用 @ 引用文件与目录&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>解释一下 @src/utils/auth.js 里的逻辑     # 引用单个文件，带上完整内容</span></span>
<span class="line"><span>@src/components 的结构是怎样的?          # 引用目录，给出文件列表（不含内容）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>@</code> 文件引用会把该文件所在目录及其父目录的 <code>CLAUDE.md</code> 一并带入上下文；可以在一条消息里引用多个文件。超过 256 KB 的文本文件被 <code>@</code> 引用时，Claude 会收到文件大小提示并分段读取（v2.1.292+）；若设了 <code>CLAUDE_CODE_DISABLE_FILE_MENTIONS=1</code>（v2.1.299+），则只把文件路径传给 Claude 由文件工具按需读取，不再直接内联内容。MCP 资源同样支持，格式为 <code>@server:resource</code>。</p><h2 id="恢复之前的会话" tabindex="-1">恢复之前的会话 <a class="header-anchor" href="#恢复之前的会话" aria-label="Permalink to &quot;恢复之前的会话&quot;">​</a></h2><p>任务跨越多次操作时，不用每次重新讲一遍背景：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --continue</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这会恢复当前目录下最近一次会话；如果没有历史会话，会提示 <code>No conversation found to continue</code> 并退出。想从列表里挑选，用 <code>claude --resume</code>，或者在会话内用 <code>/resume</code>。</p><h2 id="并行开发用-worktree" tabindex="-1">并行开发用 Worktree <a class="header-anchor" href="#并行开发用-worktree" aria-label="Permalink to &quot;并行开发用 Worktree&quot;">​</a></h2><p>在一个终端里做一个功能，另一个终端里让 Claude 修 bug，互不干扰。每个 worktree 是同一仓库下独立分支的独立检出：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --worktree</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature-auth</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>在第二个终端换个名字重复上面的命令，即可开启一个隔离的并行会话。要在一个界面里统一监控多个并行会话，用 <code>claude agents</code>（见<a href="/Front2Full/manual/agent/claude-code/commands-collaboration">并行与后台协作</a>）。</p><h2 id="先计划、再落地" tabindex="-1">先计划、再落地 <a class="header-anchor" href="#先计划、再落地" aria-label="Permalink to &quot;先计划、再落地&quot;">​</a></h2><p>想在改动落盘前先审查方案，切到计划模式。Claude 只读文件、给出计划，在你确认前不做任何修改：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --permission-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plan</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>会话中途也可以按 <code>Shift+Tab</code> 切入计划模式。</p><h2 id="把探索工作甩给-subagent" tabindex="-1">把探索工作甩给 subagent <a class="header-anchor" href="#把探索工作甩给-subagent" aria-label="Permalink to &quot;把探索工作甩给 subagent&quot;">​</a></h2><p>探索一个大代码库会把很多文件内容塞进上下文。把探索工作委托出去，只让结论回到主对话：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用一个 subagent 调查一下我们的认证系统是怎么处理 token 刷新的</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>subagent 会在自己独立的上下文窗口里读文件，只把总结报告返回主会话。更多定义与配置见 <a href="/Front2Full/manual/agent/claude-code/agents">Agents</a>。</p><h2 id="把-claude-接入脚本管道" tabindex="-1">把 Claude 接入脚本管道 <a class="header-anchor" href="#把-claude-接入脚本管道" aria-label="Permalink to &quot;把 Claude 接入脚本管道&quot;">​</a></h2><p>在 CI、pre-commit hook、批处理场景下非交互地运行 Claude。stdin/stdout 和普通 Unix 工具一样使用：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -20</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;总结这些最近的提交&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>更多输出格式、权限参数、扇出模式见<a href="/Front2Full/manual/agent/claude-code/cli-flags">启动命令行选项</a>中的非交互模式部分。</p>`,64)])])}const b=s(p,[["render",l]]);export{h as __pageData,b as default};
